import json,os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
raw=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()
grids=[]
for ln in raw.splitlines():
    if 'submit' not in ln or '"grid"' not in ln: continue
    j=json.loads(ln)
    def walk(o):
        if isinstance(o,dict):
            for v in o.values(): yield from walk(v)
        elif isinstance(o,list):
            for v in o: yield from walk(v)
        elif isinstance(o,str): yield o
    for st in walk(j):
        mm=re.search(r'"grid"\s*:\s*(\[\[.*?\]\])', st)
        if mm:
            grids.append(mm.group(1))
